create table if not exists public.content_recommendations (id uuid primary key default gen_random_uuid(), workspace_id uuid not null, business_id uuid, recommendation_date date not null default current_date, channel text, format text, topic text not null, rationale text, keywords text[] not null default '{}'::text[], cta text, draft_copy text, supporting_evidence_ids uuid[] not null default '{}'::uuid[], source_competitor_ids uuid[] not null default '{}'::uuid[], confidence numeric(5,4) not null default 0 check (confidence >= 0 and confidence <= 1), status text not null default 'suggested' check (status in ('suggested','approved','rejected','published')), created_at timestamptz not null default now(), updated_at timestamptz not null default now()); create index if not exists idx_content_recs_workspace_date on public.content_recommendations(workspace_id, recommendation_date desc); alter table public.content_recommendations enable row level security; create policy "members_read_content_recommendations" on public.content_recommendations for select to authenticated using (public.is_workspace_member(auth.uid(), workspace_id));;
